class Solution:
    def maxDistance(self, side: int, points, k: int) -> int:
        def perim(p):
            x, y = p
            if y == 0:
                return x
            elif x == side:
                return side + y
            elif y == side:
                return 2 * side + (side - x)
            else:  # x == 0
                return 3 * side + (side - y)

        ts = sorted(perim(p) for p in points)
        n = len(ts)
        P = 4 * side
        t_ext = ts + [t + P for t in ts]
        M = 2 * n

        def check(d):
            nxt = [M] * M
            j = 0
            for i in range(M):
                if j < i + 1:
                    j = i + 1
                while j < M and t_ext[j] - t_ext[i] < d:
                    j += 1
                nxt[i] = j

            for start in range(n):
                curr = start
                limit = start + n
                ok = True
                for _ in range(k - 1):
                    curr = nxt[curr]
                    if curr >= limit:
                        ok = False
                        break
                if not ok:
                    continue
                if P - (t_ext[curr] - t_ext[start]) >= d:
                    return True
            return False

        lo, hi = 0, side
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if check(mid):
                lo = mid
            else:
                hi = mid - 1
        return lo
